Dictionary DCWorldExt::read_runtime_map_lut_frame(Object *map, int64_t publication_id,
        int64_t day, int64_t generation, int cell_count, bool measure_copy) const {
    const auto fail = [](const char *reason) {
        Dictionary failure;
        failure["reason"] = reason;
        return failure;
    };
    const auto &commit = _runtime_map_display_commit;
    if (publication_id <= 0) return fail("map_lut_display_not_installed");
    if (!commit.day_tail) return fail("map_lut_publication_unavailable");
    if (!map || map != _map_data) return fail("map_lut_map_mismatch");
    if (publication_id != _runtime_map_display_id) return fail("map_lut_publication_mismatch");
    if (day != commit.header.committed_day) return fail("map_lut_day_mismatch");
    if (generation <= 0 || static_cast<uint64_t>(generation) != commit.header.generation)
        return fail("map_lut_generation_mismatch");
    if (_climate_writeback_applied_day >= 0 && _climate_writeback_applied_day != day)
        return fail("map_lut_climate_day_mismatch");

